var i=`idempotency`;var s=46;var o={en:[{id:`T046-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Idempotency`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Distributed business workflows often span independent services that cannot share one ACID transaction.`},{id:`B`,text:`An operation is idempotent when applying it more than once has the same intended effect as applying it once.`},{id:`C`,text:`Timeouts bound waiting, retries recover transient failures, and backoff spaces repeated attempts to avoid overload.`},{id:`D`,text:`Eventual consistency means replicas converge to a compatible state if updates stop and communication proceeds, under the system's stated assumptions.`}]},{id:`T046-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Idempotency`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Use finite deadlines, exponential backoff with jitter, retryable-error classification and limits on attempt count.`},{id:`B`,text:`Use request-scoped idempotency keys, deduplication stores and atomic association of a result with its key.`},{id:`C`,text:`Atomicity means all-or-nothing; consistency preserves declared constraints when transactions are correct; isolation addresses interfering operations; durability retains committed results after specified failures.`},{id:`D`,text:`Distinguish stale reads, concurrent conflicting writes, causal ordering and convergence policy.`}]},{id:`T046-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A client retries a card payment after timeout.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`An international product catalog may read nearby replicas for speed, while inventory reservation routes through a leader or quorum to prevent double allocation.`},{id:`B`,text:`If an external currency-rate API becomes unavailable, a checkout may temporarily use the last verified rate when policy allows, or fail fast without tying up every request worker.`},{id:`C`,text:`Reusing its idempotency key must return the original outcome, not issue a second charge, even if the first response was lost.`},{id:`D`,text:`If the write fails, neither partial operation should become visible as successful.`}]},{id:`T046-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Idempotency`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Do not classify every database permanently as CA, CP or AP; behavior is operation-specific and depends on fault assumptions.`},{id:`B`,text:`Blindly retrying card charges can double-bill; long timeouts can exhaust connection pools.`},{id:`C`,text:`Exactly-once effects across arbitrary components are difficult; most systems build at-least-once delivery plus idempotent processing.`},{id:`D`,text:`Wrong thresholds can trip on harmless fluctuations or keep calling a failing service.`}]},{id:`T046-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`In distributed applications it makes retries safe despite ambiguous network outcomes.`}]}]},{id:`T046-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A POST request is automatically idempotent if the server returns HTTP 200.`}]}]},{id:`T046-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Keys reused with different requests must not silently produce misleading results.`}]}]},{id:`T046-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Idempotency`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Reusing the same key with a different payment payload should silently create a new charge.`},{id:`B`,text:`Use request-scoped idempotency keys, deduplication stores and atomic association of a result with its key.`},{id:`C`,text:`An operation is idempotent when applying it more than once has the same intended effect as applying it once.`},{id:`D`,text:`A saga provides a global ACID rollback across independent services.`}]},{id:`T046-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Idempotency`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Keys reused with different requests must not silently produce misleading results.`},{id:`B`,text:`A POST request is automatically idempotent if the server returns HTTP 200.`},{id:`C`,text:`Reusing its idempotency key must return the original outcome, not issue a second charge, even if the first response was lost.`},{id:`D`,text:`Atomicity means every partial debit can remain committed after a failed transfer.`}]},{id:`T046-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A client retries a card payment after timeout.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to implement an idempotent payment endpoint with persistence-backed keys. Test duplicate requests, concurrent races, different payloads and process restart.`},{id:`B`,text:`Ask an agent to design reservation confirmation under a simulated partition, specifying exact success, timeout and retry semantics rather than a generic CP/AP label.`},{id:`C`,text:`Ask an agent to wrap an unreliable provider with timeout, circuit breaker and metrics. Test transitions across healthy, degraded and recovering states.`},{id:`D`,text:`Have an agent implement a webhook client with deadlines, capped exponential backoff and jitter. Verify attempt limits, classification of permanent errors and idempotent delivery.`}]},{id:`T046-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`At what exact point must the key and business result become atomic?`}]}]},{id:`T046-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A client retries a card payment after timeout.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Idempotency`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T046-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A client retries a card payment after timeout.`,b:!0},{t:` — propose three checks for `},{t:`Idempotency`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T046-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A client retries a card payment after timeout.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T046-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Idempotency`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A client retries a card payment after timeout.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T046-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Ідемпотентність`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Розподілені бізнес-процеси часто охоплюють сервіси без спільної ACID-транзакції.`},{id:`B`,text:`Операція ідемпотентна, коли багаторазове виконання має той самий очікуваний ефект, що й одноразове.`},{id:`C`,text:`Timeout обмежує очікування, retry долає тимчасові збої, backoff розносить спроби в часі, щоб не перевантажувати систему.`},{id:`D`,text:`Кінцева узгодженість означає, що репліки зійдуться до сумісного стану, якщо оновлення припиняться й комунікація відновиться за визначених припущень.`}]},{id:`T046-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Ідемпотентність`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Використовуйте кінцевий deadline, експоненційний backoff з jitter, класифікацію помилок і ліміти спроб.`},{id:`B`,text:`Застосовуйте ключі ідемпотентності, сховище дедуплікації та атомарне зв’язування ключа з результатом.`},{id:`C`,text:`Атомарність означає «все або нічого»; узгодженість зберігає задекларовані обмеження за коректних транзакцій; ізоляція контролює вплив паралельних операцій; довговічність зберігає committed результат після передбачених відмов.`},{id:`D`,text:`Розрізняйте застарілі читання, конфліктні одночасні записи, причинний порядок і правила зближення станів.`}]},{id:`T046-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Клієнт повторює картковий платіж після timeout.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Міжнародний каталог може читати найближчі репліки заради швидкості, а резервування складу спрямовувати через лідера або quorum, щоб уникнути подвійного виділення.`},{id:`B`,text:`Якщо зовнішнє API валют недоступне, checkout може тимчасово застосувати останній підтверджений курс, якщо політика це дозволяє, або швидко завершитися з помилкою без блокування воркерів.`},{id:`C`,text:`Повтор ключа має повертати початковий результат, а не виконувати друге списання, навіть якщо перша відповідь загубилась.`},{id:`D`,text:`Якщо запис не вдався, жоден частковий результат не має вважатися успіхом.`}]},{id:`T046-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Ідемпотентність`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Не навішуйте назавжди ярлик CA, CP чи AP на будь-яку БД: поведінка залежить від операцій і моделі відмов.`},{id:`B`,text:`Сліпі повтори платіжного списання можуть подвоїти оплату; довгі timeout виснажують пул з’єднань.`},{id:`C`,text:`Exactly-once ефект між довільними компонентами складний; зазвичай поєднують at-least-once доставку та ідемпотентну обробку.`},{id:`D`,text:`Неправильні пороги реагують на дрібні коливання або надто довго викликають зламаний сервіс.`}]},{id:`T046-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`У розподілених застосунках це робить повтори безпечними за невизначеного мережевого результату.`}]}]},{id:`T046-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`POST-запит автоматично ідемпотентний, якщо сервер повертає HTTP 200.`}]}]},{id:`T046-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Повтор ключа з іншим запитом не можна непомітно трактувати як той самий платіж.`}]}]},{id:`T046-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Ідемпотентність`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Повтор ключа з іншим платіжним payload має непомітно створити нове списання.`},{id:`B`,text:`Застосовуйте ключі ідемпотентності, сховище дедуплікації та атомарне зв’язування ключа з результатом.`},{id:`C`,text:`Операція ідемпотентна, коли багаторазове виконання має той самий очікуваний ефект, що й одноразове.`},{id:`D`,text:`Saga забезпечує глобальний ACID-відкат між незалежними сервісами.`}]},{id:`T046-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Ідемпотентність`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Повтор ключа з іншим запитом не можна непомітно трактувати як той самий платіж.`},{id:`B`,text:`POST-запит автоматично ідемпотентний, якщо сервер повертає HTTP 200.`},{id:`C`,text:`Повтор ключа має повертати початковий результат, а не виконувати друге списання, навіть якщо перша відповідь загубилась.`},{id:`D`,text:`Атомарність дозволяє залишити часткове списання після невдалого переказу.`}]},{id:`T046-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Клієнт повторює картковий платіж після timeout.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента реалізувати платіжний endpoint з ключами в БД. Перевірте дублікати, одночасні запити, різні payload і перезапуск процесу.`},{id:`B`,text:`Попросіть агента спроєктувати підтвердження бронювання під час мережевого розділення, явно визначити успіх, timeout і повтори замість загальної позначки CP/AP.`},{id:`C`,text:`Попросіть агента обгорнути нестабільного провайдера timeout, Circuit Breaker і метриками. Протестуйте переходи між нормою, деградацією та відновленням.`},{id:`D`,text:`Попросіть агента реалізувати webhook-клієнт із deadline, обмеженим експоненційним backoff та jitter. Перевірте ліміт спроб, постійні помилки й ідемпотентність.`}]},{id:`T046-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У якій саме точці ключ і бізнес-результат мають фіксуватися атомарно?`}]}]},{id:`T046-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Клієнт повторює картковий платіж після timeout.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Ідемпотентність`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T046-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Клієнт повторює картковий платіж після timeout.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Ідемпотентність`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T046-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Клієнт повторює картковий платіж після timeout.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T046-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Ідемпотентність`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Клієнт повторює картковий платіж після timeout.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var n={slug:i,topicId:46,questions:o};export{n as default,o as questions,i as slug,s as topicId};